import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:pen_zz/core/gear.dart';
import 'package:pen_zz/core/rig.dart';
import 'package:pen_zz/core/strokes.dart';

/// Compares the Dart gear math with values produced by the original web game
/// (test/fixtures/gear_golden.json, generated by tool/parity/gen-golden.mjs).
void main() {
  final golden = jsonDecode(File('test/fixtures/gear_golden.json').readAsStringSync()) as Map<String, dynamic>;

  Strokes strokesOf(dynamic raw) => [
        for (final s in raw as List) [for (final v in s as List) (v as num).toDouble()],
      ];

  void close(num actual, num expected, String what) {
    expect(actual.toDouble(), closeTo(expected.toDouble(), 1e-6 + expected.abs() * 1e-9), reason: what);
  }

  test('weapon grip at rest matches', () {
    final h = golden['hand0'] as List;
    close(hand0.x, h[0] as num, 'hand0.x');
    close(hand0.y, h[1] as num, 'hand0.y');
  });

  test('weapon stats match the web game', () {
    for (final w in golden['weapons'] as List) {
      final id = w['id'];
      final e = w['expect'] as Map<String, dynamic>;
      final st = weaponStats(strokesOf(w['strokes']));
      close(st.ink, e['L'] as num, '$id ink');
      close(st.len, e['len'] as num, '$id len');
      close(st.wid, e['wid'] as num, '$id wid');
      close(st.windup, e['windup'] as num, '$id windup');
      close(st.strike, e['strike'] as num, '$id strike');
      close(st.recover, e['recover'] as num, '$id recover');
      close(st.reach, e['reach'] as num, '$id reach');
      close(st.kP, e['P'] as num, '$id P');
      close(st.kD, e['D'] as num, '$id D');
      expect(st.tip, e['tip'], reason: '$id tip');
      expect(st.pts.length, e['n'], reason: '$id points');
    }
  });

  test('shield stats match the web game', () {
    for (final s in golden['shields'] as List) {
      final id = s['id'];
      final e = s['expect'] as Map<String, dynamic>;
      final st = shieldStats(strokesOf(s['strokes']));
      close(st.ink, e['L'] as num, '$id ink');
      expect(st.has, e['has'], reason: '$id has');
      close(st.h, e['H'] as num, '$id H');
      close(st.w, e['W'] as num, '$id W');
      close(st.cx, e['cx'] as num, '$id cx');
      close(st.cy, e['cy'] as num, '$id cy');
      close(st.coverage, e['coverage'] as num, '$id coverage');
      close(st.raise, e['raise'] as num, '$id raise');
      close(st.lower, e['lower'] as num, '$id lower');
      expect(st.pts.length, e['n'], reason: '$id points');
    }
  });

  test('strike hand path matches', () {
    for (final h in golden['hands'] as List) {
      final p = strikeHand((h['th'] as num).toDouble());
      final e = h['hand'] as List;
      close(p.x, e[0] as num, 'hand x at ${h['th']}');
      close(p.y, e[1] as num, 'hand y at ${h['th']}');
    }
  });

  test('rig solves the same joints', () {
    final rigs = golden['rigs'] as Map<String, dynamic>;
    final poses = {'rest': restPose, 'wind': windPose, 'end': endPose};
    for (final entry in poses.entries) {
      final r = solveRig(entry.value);
      final e = rigs[entry.key] as Map<String, dynamic>;
      for (final joint in {
        'neck': r.neck,
        'sh': r.sh,
        'head': r.head,
        'kneeF': r.kneeF,
        'footF': r.footF,
        'kneeB': r.kneeB,
        'footB': r.footB,
        'elbW': r.elbW,
        'handW': r.handW,
        'elbS': r.elbS,
        'handS': r.handS,
      }.entries) {
        final v = e[joint.key] as List;
        close(joint.value.x, v[0] as num, '${entry.key}.${joint.key}.x');
        close(joint.value.y, v[1] as num, '${entry.key}.${joint.key}.y');
      }
    }
  });
}
